        back = (
            '<a href="
        ) % escape(key)
        text = text.rstrip()
        if text.endswith('</p>'):
            text = re.sub(r'<\/p>$', r'%s</p>' % back, text)
        else:
            text = '%s<p>%s</p>' % (text, back)
        html = '<li id="fn-%s">%s</li>\n' % (escape(key), text)
        return html
    def footnotes(self, text):
        """Wrapper for all footnotes.
        :param text: contents of all footnotes.
