        tmp_name = self.gen_tmp_name()
        converter = self.protect_unpack_sequence(
            target,
            ast.Name(tmp_name, ast.Load()))
        try_body = [ast.Assign(targets=[target], value=converter)]
        finalbody = [self.gen_del_stmt(tmp_name)]
