    if ast_return_t is None:
        return ["pass"], 0, 0
    return_t = new_type_to_old_type(ast_return_t)
    check_assign(dummy_node_for_type(return_t), dummy_node_for_type(contract_sig.return_type))
    return_t = calculate_type_for_external_return(return_t)
    abi_return_t = return_t.abi_type
    min_return_size = abi_return_t.min_size()
    max_return_size = abi_return_t.size_bound()
    assert 0 < min_return_size <= max_return_size
    ret_ofst = buf
    ret_len = max_return_size
    ret = []
    if not skip_contract_check:
        ret += [["assert", ["ge", "returndatasize", min_return_size]]]
    encoding = Encoding.ABI
    buf = IRnode.from_list(
        buf,
        typ=return_t,
        location=MEMORY,
        encoding=encoding,
        annotation=f"{expr.node_source_code} returndata buffer",
    )
    assert isinstance(return_t, TupleType)
    if needs_clamp(return_t, encoding):
        buf2 = IRnode.from_list(
            context.new_internal_variable(return_t), typ=return_t, location=MEMORY
        )
        ret.append(make_setter(buf2, buf))
        ret.append(buf2)
    else:
        ret.append(buf)
    return ret, ret_ofst, ret_len
def _external_call_helper(
    contract_address,
    contract_sig,
    args_ir,
    context,
    value=None,
    gas=None,
    skip_contract_check=None,
    expr=None,
):
    if value is None:
        value = 0
    if gas is None:
        gas = "gas"
    if skip_contract_check is None:
        skip_contract_check = False
    assert len(contract_sig.base_args) <= len(args_ir) <= len(contract_sig.args)
    if context.is_constant() and contract_sig.mutability not in ("view", "pure"):
        raise StateAccessViolation(
            f"May not call state modifying function '{contract_sig.name}' "
            f"within {context.pp_constancy()}.",
            expr,
        )
    sub = ["seq"]
    buf, arg_packer, args_ofst, args_len = _pack_arguments(contract_sig, args_ir, context)
    ret_unpacker, ret_ofst, ret_len = _unpack_returndata(
        buf, contract_sig, skip_contract_check, context, expr
    )
    sub += arg_packer
    if contract_sig.return_type is None and not skip_contract_check:
        sub.append(["assert", ["extcodesize", contract_address]])
    if context.is_constant() or contract_sig.mutability in ("view", "pure"):
        call_op = ["staticcall", gas, contract_address, args_ofst, args_len, ret_ofst, ret_len]
    else:
        call_op = ["call", gas, contract_address, value, args_ofst, args_len, ret_ofst, ret_len]
    sub.append(check_external_call(call_op))
    if contract_sig.return_type is not None:
        sub += ret_unpacker
    return IRnode.from_list(sub, typ=contract_sig.return_type, location=MEMORY)
def ir_for_external_call(stmt_expr, context):
    from vyper.codegen.expr import Expr
    contract_address = Expr.parse_value_expr(stmt_expr.func.value, context)
    value, gas, skip_contract_check = _get_special_kwargs(stmt_expr, context)
    args_ir = [Expr(x, context).ir_node for x in stmt_expr.args]
    assert isinstance(contract_address.typ, InterfaceType)
    contract_name = contract_address.typ.name
    method_name = stmt_expr.func.attr
    contract_sig = context.sigs[contract_name][method_name]
    ret = _external_call_helper(
        contract_address,
        contract_sig,
        args_ir,
        context,
        value=value,
        gas=gas,
        skip_contract_check=skip_contract_check,
        expr=stmt_expr,
    )
    ret.annotation = stmt_expr.get("node_source_code")
    return ret
def _register_function_args(context: Context, sig: FunctionSignature) -> List[IRnode]:
    ret = []
    base_args_t = TupleType([arg.typ for arg in sig.base_args])
    if sig.is_init_func:
        base_args_ofst = IRnode(0, location=DATA, typ=base_args_t, encoding=Encoding.ABI)
    else:
        base_args_ofst = IRnode(4, location=CALLDATA, typ=base_args_t, encoding=Encoding.ABI)
    for i, arg in enumerate(sig.base_args):
        arg_ir = get_element_ptr(base_args_ofst, i)
        if needs_clamp(arg.typ, Encoding.ABI):
            p = context.new_variable(arg.name, arg.typ, is_mutable=False)
            dst = IRnode(p, typ=arg.typ, location=MEMORY)
            copy_arg = make_setter(dst, arg_ir)
            copy_arg.source_pos = getpos(arg.ast_source)
            ret.append(copy_arg)
        else:
            assert abi_encoding_matches_vyper(arg.typ)
            context.vars[arg.name] = VariableRecord(
                name=arg.name,
                pos=arg_ir,
                typ=arg.typ,
                mutable=False,
                location=arg_ir.location,
                encoding=Encoding.ABI,
            )
    return ret
def generate_ir_for_external_function(code, sig, context, check_nonpayable):
    """Return the IR for an external function. Includes code to inspect the method_id,
    enter the function (nonpayable and reentrancy checks), handle kwargs and exit
    the function (clean up reentrancy storage variables)
    """
    func_type = code._metadata["type"]
    nonreentrant_pre, nonreentrant_post = get_nonreentrant_lock(func_type)
    handle_base_args = _register_function_args(context, sig)
    kwarg_handlers = _generate_kwarg_handlers(context, sig)
    body = ["seq"]
    body += handle_base_args
    if check_nonpayable and sig.mutability != "payable":
        body += [["assert", ["iszero", "callvalue"]]]
    body += nonreentrant_pre
    body += [parse_body(code.body, context, ensure_terminated=True)]
    body = ["label", sig.external_function_base_entry_label, ["var_list"], body]
    exit_sequence = ["seq"] + nonreentrant_post
    if sig.is_init_func:
        pass
    elif context.return_type is None:
        exit_sequence += [["stop"]]
    else:
        exit_sequence += [["return", "ret_ofst", "ret_len"]]
    exit_sequence_args = ["var_list"]
    if context.return_type is not None:
        exit_sequence_args += ["ret_ofst", "ret_len"]
    exit = ["label", sig.exit_sequence_label, exit_sequence_args, exit_sequence]
    func_common_ir = ["seq", body, exit]
    if sig.is_default_func or sig.is_init_func:
        ret = ["seq"]
        ret.append(["goto", sig.external_function_base_entry_label])
        ret.append(func_common_ir)
    else:
        ret = kwarg_handlers
        ret[-1][-1].append(func_common_ir)
    return IRnode.from_list(ret)
MEMORY = AddrSpace("memory", 32, "mload", "mstore")
STORAGE = AddrSpace("storage", 1, "sload", "sstore")
CALLDATA = AddrSpace("calldata", 32, "calldataload")
DATA = AddrSpace("data", 32, "dload")
    def parse_Attribute(self):
        if self.expr.attr == "balance":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if is_base_type(addr.typ, "address"):
                if (
                    isinstance(self.expr.value, vy_ast.Name)
                    and self.expr.value.id == "self"
                    and version_check(begin="istanbul")
                ):
                    seq = ["selfbalance"]
                else:
                    seq = ["balance", addr]
                return IRnode.from_list(seq, typ=BaseType("uint256"))
        elif self.expr.attr == "codesize" or self.expr.attr == "is_contract":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if is_base_type(addr.typ, "address"):
                if self.expr.attr == "codesize":
                    if self.expr.value.id == "self":
                        eval_code = ["codesize"]
                    else:
                        eval_code = ["extcodesize", addr]
                    output_type = "uint256"
                else:
                    eval_code = ["gt", ["extcodesize", addr], 0]
                    output_type = "bool"
                return IRnode.from_list(eval_code, typ=BaseType(output_type))
        elif self.expr.attr == "codehash":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if not version_check(begin="constantinople"):
                raise EvmVersionException(
                    "address.codehash is unavailable prior to constantinople ruleset", self.expr
                )
            if is_base_type(addr.typ, "address"):
                return IRnode.from_list(["extcodehash", addr], typ=BaseType("bytes32"))
        elif self.expr.attr == "code":
            addr = Expr.parse_value_expr(self.expr.value, self.context)
            if is_base_type(addr.typ, "address"):
                if addr.value == "address":
                    return IRnode.from_list(["~selfcode"], typ=ByteArrayType(0))
                return IRnode.from_list(["~extcode", addr], typ=ByteArrayType(0))
        elif isinstance(self.expr.value, vy_ast.Name) and self.expr.value.id == "self":
            type_ = self.expr._metadata["type"]
            var = self.context.globals[self.expr.attr]
            return IRnode.from_list(
                type_.position.position,
                typ=var.typ,
                location=STORAGE,
                annotation="self." + self.expr.attr,
            )
        elif (
            isinstance(self.expr.value, vy_ast.Name) and self.expr.value.id in ENVIRONMENT_VARIABLES
        ):
            key = f"{self.expr.value.id}.{self.expr.attr}"
            if key == "msg.sender":
                return IRnode.from_list(["caller"], typ="address")
            elif key == "msg.data":
                return IRnode.from_list(["~calldata"], typ=ByteArrayType(0))
            elif key == "msg.value" and self.context.is_payable:
                return IRnode.from_list(["callvalue"], typ=BaseType("uint256"))
            elif key == "msg.gas":
                return IRnode.from_list(["gas"], typ="uint256")
            elif key == "block.difficulty":
                return IRnode.from_list(["difficulty"], typ="uint256")
            elif key == "block.timestamp":
                return IRnode.from_list(["timestamp"], typ=BaseType("uint256"))
            elif key == "block.coinbase":
                return IRnode.from_list(["coinbase"], typ="address")
            elif key == "block.number":
                return IRnode.from_list(["number"], typ="uint256")
            elif key == "block.gaslimit":
                return IRnode.from_list(["gaslimit"], typ="uint256")
            elif key == "block.basefee":
                return IRnode.from_list(["basefee"], typ="uint256")
            elif key == "block.prevhash":
                return IRnode.from_list(["blockhash", ["sub", "number", 1]], typ="bytes32")
            elif key == "tx.origin":
                return IRnode.from_list(["origin"], typ="address")
            elif key == "tx.gasprice":
                return IRnode.from_list(["gasprice"], typ="uint256")
            elif key == "chain.id":
                if not version_check(begin="istanbul"):
                    raise EvmVersionException(
                        "chain.id is unavailable prior to istanbul ruleset", self.expr
                    )
                return IRnode.from_list(["chainid"], typ="uint256")
        else:
            sub = Expr(self.expr.value, self.context).ir_node
            if isinstance(sub.typ, InterfaceType):
                return sub
            if isinstance(sub.typ, StructType) and self.expr.attr in sub.typ.members:
                return get_element_ptr(sub, self.expr.attr)
    def _assert_reason(self, test_expr, msg):
        if isinstance(msg, vy_ast.Name) and msg.id == "UNREACHABLE":
            return IRnode.from_list(["assert_unreachable", test_expr])
        try:
            tmp = self.context.constancy
            self.context.constancy = Constancy.Constant
            msg_ir = Expr(msg, self.context).ir_node
        finally:
            self.context.constancy = tmp
        def _get_last(ir):
            if len(ir.args) == 0:
                return ir.value
            return _get_last(ir.args[-1])
        if msg_ir.location != MEMORY:
            buf = self.context.new_internal_variable(msg_ir.typ)
            instantiate_msg = make_byte_array_copier(buf, msg_ir)
        else:
            buf = _get_last(msg_ir)
            if not isinstance(buf, int):
                raise CompilerPanic(f"invalid bytestring {buf}\n{self}")
            instantiate_msg = msg_ir
        method_id = util.abi_method_id("Error(string)")
        assert buf >= 36, "invalid buffer"
        _runtime_length = ["mload", buf]
        revert_seq = [
            "seq",
            instantiate_msg,
            zero_pad(buf),
            ["mstore", buf - 64, method_id],
            ["mstore", buf - 32, 0x20],
            ["revert", buf - 36, ["add", 4 + 32 + 32, ["ceil32", _runtime_length]]],
        ]
        if test_expr is not None:
            ir_node = ["if", ["iszero", test_expr], revert_seq]
        else:
            ir_node = revert_seq
        return IRnode.from_list(ir_node)
    def build_IR(self, expr, args, kwargs, context):
        to, data = args
        gas, value, outsize, delegate_call, static_call, revert_on_failure = (
            kwargs["gas"],
            kwargs["value"],
            kwargs["max_outsize"],
            kwargs["is_delegate_call"],
            kwargs["is_static_call"],
            kwargs["revert_on_failure"],
        )
        for key in ("is_delegate_call", "is_static_call", "revert_on_failure"):
            if kwargs[key].typ.is_literal is False:
                raise TypeMismatch(
                    f"The `{key}` parameter must be a static/literal boolean value", expr
                )
        revert_on_failure = revert_on_failure.value == 1
        static_call = static_call.value == 1
        delegate_call = delegate_call.value == 1
        if delegate_call and static_call:
            raise ArgumentException(
                "Call may use one of `is_delegate_call` or `is_static_call`, not both", expr
            )
        if not static_call and context.is_constant():
            raise StateAccessViolation(
                f"Cannot make modifying calls from {context.pp_constancy()},"
                " use `is_static_call=True` to perform this action",
                expr,
            )
        eval_input_buf = ensure_in_memory(data, context)
        input_buf = eval_seq(eval_input_buf)
        output_node = IRnode.from_list(
            context.new_internal_variable(ByteArrayType(outsize)),
            typ=ByteArrayType(outsize),
            location=MEMORY,
        )
        bool_ty = BaseType("bool")
        if input_buf is None:
            call_ir = ["with", "arg_buf", eval_input_buf]
            input_buf = IRnode.from_list("arg_buf")
        else:
            call_ir = ["seq", eval_input_buf]
        common_call_args = [
            add_ofst(input_buf, 32),
            ["mload", input_buf],
            add_ofst(output_node, 32) if outsize else 0,
            outsize,
        ]
        if delegate_call:
            call_op = ["delegatecall", gas, to, *common_call_args]
        elif static_call:
            call_op = ["staticcall", gas, to, *common_call_args]
        else:
            call_op = ["call", gas, to, value, *common_call_args]
        call_ir += [call_op]
        if outsize:
            size = [
                "with",
                "_l",
                outsize,
                ["with", "_r", "returndatasize", ["if", ["gt", "_l", "_r"], "_r", "_l"]],
            ]
            store_output_size = [
                "with",
                "output_pos",
                output_node,
                ["seq", ["mstore", "output_pos", size], "output_pos"],
            ]
            bytes_ty = ByteArrayType(outsize)
            if revert_on_failure:
                typ = bytes_ty
                ret_ir = ["seq", check_external_call(call_ir), store_output_size]
            else:
                typ = TupleType([bool_ty, bytes_ty])
                ret_ir = [
                    "multi",
                    IRnode.from_list(call_ir, typ=bool_ty),
                    IRnode.from_list(store_output_size, typ=bytes_ty, location=MEMORY),
                ]
        else:
            if revert_on_failure:
                typ = None
                ret_ir = check_external_call(call_ir)
            else:
                typ = bool_ty
                ret_ir = call_ir
        return IRnode.from_list(ret_ir, typ=typ, location=MEMORY)

class ExtractDetails(object):
class ExtractInfo(object):
class Extractor(Module):
    UNIQUE_PATH_DELIMITER = '%%'
    def add_pending(self, f):
        if os.path.islink(f):
            return
        try:
            file_mode = os.stat(f).st_mode
        except OSError as e:
            return
        if stat.S_ISREG(file_mode):
            try:
                fp = binwalk.core.common.BlockFile(f)
                fp.close()
                self.pending.append(f)
            except IOError as e:
                binwalk.core.common.warning("Ignoring file '%s': %s" % (f, str(e)))
        else:
            binwalk.core.common.warning("Ignoring file '%s': Not a regular file" % f)
    def callback(self, r):
        try:
            r.file.size
        except KeyboardInterrupt as e:
            pass
        except Exception as e:
            return
        if not r.size:
            size = r.file.size - r.offset
        else:
            size = r.size
        if r.valid and r.extract and r.display and (not self.max_count or self.extraction_count < self.max_count):
            if not binwalk.core.common.has_key(self.output, r.file.path):
                self.output[r.file.path] = ExtractInfo()
            binwalk.core.common.debug("Extractor callback for %s @%d [%s]" % (r.file.name,
                                                                              r.offset,
                                                                              r.description))
            (extraction_directory, dd_file, scan_extracted_files, extraction_utility) = self.extract(r.offset,
                                                                                                     r.description,
                                                                                                     r.file.path,
                                                                                                     size,
                                                                                                     r.name)
            if extraction_directory and dd_file:
                self.extraction_count += 1
                dd_file_path = os.path.join(extraction_directory, dd_file)
                self.output[r.file.path].carved[r.offset] = dd_file_path
                self.output[r.file.path].extracted[r.offset] = ExtractDetails(files=[], command=extraction_utility)
                directory_listing = set(os.listdir(extraction_directory))
                if not has_key(self.last_directory_listing, extraction_directory):
                    self.last_directory_listing[extraction_directory] = set()
                for f in directory_listing.difference(self.last_directory_listing[extraction_directory]):
                    file_path = os.path.join(extraction_directory, f)
                    real_file_path = os.path.realpath(file_path)
                    self.result(description=file_path, display=False)
                    if real_file_path != dd_file_path:
                        binwalk.core.common.debug("Adding %s (%s) (%s) to file list" % (file_path, f, real_file_path))
                        self.output[r.file.path].extracted[r.offset].files.append(file_path)
                    if (self.matryoshka and
                        file_path != dd_file_path and
                        scan_extracted_files and
                            self.directory in real_file_path):
                        if len(real_file_path.split(self.directory)[1].split(os.path.sep)) <= self.matryoshka:
                            if os.path.isdir(file_path):
                                for root, dirs, files in os.walk(file_path):
                                    for f in files:
                                        full_path = os.path.join(root, f)
                                        self.add_pending(full_path)
                            else:
                                self.add_pending(file_path)
                self.last_directory_listing[
                    extraction_directory] = directory_listing
    def build_output_directory(self, path):
        '''
        Set the output directory for extracted files.
        @path - The path to the file that data will be extracted from.
        Returns None.
        '''
        if not has_key(self.extraction_directories, path):
            basedir = os.path.dirname(path)
            basename = os.path.basename(path)
            if basedir != self.directory:
                try:
                    subdir = basedir.split(self.directory)[1][1:]
                except IndexError as e:
                    subdir = ""
            else:
                subdir = ""
            if self.output_directory_override:
                output_directory = os.path.join(self.directory, subdir, self.output_directory_override)
            else:
                outdir = os.path.join(self.directory, subdir, '_' + basename)
                output_directory = unique_file_name(outdir, extension='extracted')
            if not os.path.exists(output_directory):
                os.mkdir(output_directory)
            self.extraction_directories[path] = output_directory
            self.output[path].directory = os.path.realpath(output_directory) + os.path.sep
        else:
            output_directory = self.extraction_directories[path]
        return output_directory
    def extract(self, offset, description, file_name, size, name=None):
        '''
        Extract an embedded file from the target file, if it matches an extract rule.
        Called automatically by Binwalk.scan().
        @offset      - Offset inside the target file to begin the extraction.
        @description - Description of the embedded file to extract, as returned by libmagic.
        @file_name   - Path to the target file.
        @size        - Number of bytes to extract.
        @name        - Name to save the file as.
        Returns the name of the extracted file (blank string if nothing was extracted).
        '''
        fname = ''
        rule = None
        recurse = False
        command_line = ''
        original_dir = os.getcwd()
        rules = self.match(description)
        file_path = os.path.realpath(file_name)
        if not rules:
            binwalk.core.common.debug("No extraction rules found for '%s'" % description)
            return (None, None, False, str(None))
        else:
            binwalk.core.common.debug("Found %d matching extraction rules" % len(rules))
        output_directory = self.build_output_directory(file_name)
        if not size:
            size = file_size(file_path) - offset
        if os.path.isfile(file_path):
            binwalk.core.common.debug("Changing directory to: %s" % output_directory)
            os.chdir(output_directory)
            if self.extract_into_subdirs:
                offset_dir = "0x%X" % offset
                os.mkdir(offset_dir)
                os.chdir(offset_dir)
            for i in range(0, len(rules)):
                rule = rules[i]
                binwalk.core.common.debug("Processing extraction rule
                if rule['recurse'] in [True, False]:
                    recurse = rule['recurse']
                else:
                    recurse = True
                binwalk.core.common.debug("Extracting %s[%d:] to %s" % (file_path, offset, name))
                fname = self._dd(file_path, offset, size, rule['extension'], output_file_name=name)
                if rule['cmd']:
                    if self.remove_after_execute:
                        fname_md5 = file_md5(fname)
                    binwalk.core.common.debug("Executing extraction command %s" % (str(rule['cmd'])))
                    if self.run_extractors:
                        (extract_ok, command_line) = self.execute(rule['cmd'], fname, rule['codes'])
                    else:
                        extract_ok = True
                        command_line = ''
                    binwalk.core.common.debug("Ran extraction command: %s" % command_line)
                    binwalk.core.common.debug("Extraction successful: %s" % extract_ok)
                    if self.remove_after_execute and (extract_ok == True or i == (len(rules) - 1)):
                        try:
                            if file_md5(fname) == fname_md5:
                                os.unlink(fname)
                        except KeyboardInterrupt as e:
                            raise e
                        except Exception as e:
                            pass
                    if extract_ok == True:
                        break
                    elif i != (len(rules) - 1):
                        try:
                            os.unlink(fname)
                        except KeyboardInterrupt as e:
                            raise e
                        except Exception as e:
                            pass
                else:
                    break
            binwalk.core.common.debug("Changing directory back to: %s" % original_dir)
            os.chdir(original_dir)
        return (output_directory, fname, recurse, command_line)
    def match(self, description):
        '''
        Check to see if the provided description string matches an extract rule.
        Called internally by self.extract().
        @description - Description string to check.
        Returns the associated rule dictionary if a match is found.
        Returns None if no match is found.
        '''
        rules = []
        ordered_rules = []
        description = description.lower()
        for rule in self.extract_rules:
            if rule['regex'].search(description):
                rules.append(rule)
        for rule in rules:
            if callable(rule['cmd']):
                ordered_rules.append(rule)
        for rule in rules:
            if not callable(rule['cmd']):
                ordered_rules.append(rule)
        binwalk.core.common.debug("Found %d/%d matches for '%s'" % (len(ordered_rules), len(self.extract_rules), description))
        return ordered_rules
    def _dd(self, file_name, offset, size, extension, output_file_name=None):
        '''
        Extracts a file embedded inside the target file.
        @file_name        - Path to the target file.
        @offset           - Offset inside the target file where the embedded file begins.
        @size             - Number of bytes to extract.
        @extension        - The file exension to assign to the extracted file on disk.
        @output_file_name - The requested name of the output file.
        Returns the extracted file name.
        '''
        total_size = 0
        default_bname = "%X" % (offset + self.config.base)
        if output_file_name is not None:
            output_file_name = str(output_file_name)
        if self.max_size and size > self.max_size:
            size = self.max_size
        if not output_file_name or output_file_name is None:
            bname = default_bname
        else:
            bname = os.path.basename(output_file_name)
        fname = unique_file_name(bname, extension)
        try:
            if self.config.swap_size:
                adjust = offset % self.config.swap_size
            else:
                adjust = 0
            offset -= adjust
            fdin = self.config.open_file(file_name)
            fdin.seek(offset)
            try:
                fdout = BlockFile(fname, 'w')
            except KeyboardInterrupt as e:
                raise e
            except Exception as e:
                fname = unique_file_name(default_bname, extension)
                fdout = BlockFile(fname, 'w')
            while total_size < size:
                (data, dlen) = fdin.read_block()
                if dlen < 1:
                    break
                else:
                    total_size += (dlen - adjust)
                    if total_size > size:
                        dlen -= (total_size - size)
                    fdout.write(str2bytes(data[adjust:dlen]))
                    adjust = 0
            fdout.close()
            fdin.close()
        except KeyboardInterrupt as e:
            raise e
        except Exception as e:
            raise Exception("Extractor.dd failed to extract data from '%s' to '%s': %s" %
                            (file_name, fname, str(e)))
        binwalk.core.common.debug("Carved data block 0x%X - 0x%X from '%s' to '%s'" %
                                  (offset, offset + size, file_name, fname))
        return fname
    def execute(self, cmd, fname, codes=[0, None]):
        '''
        Execute a command against the specified file.
        @cmd   - Command to execute.
        @fname - File to run command against.
        @codes - List of return codes indicating cmd success.
        Returns True on success, False on failure, or None if the external extraction utility could not be found.
        '''
        tmp = None
        rval = 0
        retval = True
        command_list = []
        binwalk.core.common.debug("Running extractor '%s'" % str(cmd))
        try:
            if callable(cmd):
                command_list.append(get_class_name_from_method(cmd))
                try:
                    retval = cmd(fname)
                except KeyboardInterrupt as e:
                    raise e
                except Exception as e:
                    retval = False
                    binwalk.core.common.warning("Internal extractor '%s' failed with exception: '%s'" % (str(cmd), str(e)))
            elif cmd:
                if not binwalk.core.common.DEBUG:
                    tmp = tempfile.TemporaryFile()
                while self.UNIQUE_PATH_DELIMITER in cmd:
                    need_unique_path = cmd.split(self.UNIQUE_PATH_DELIMITER)[
                        1].split(self.UNIQUE_PATH_DELIMITER)[0]
                    unique_path = binwalk.core.common.unique_file_name(need_unique_path)
                    cmd = cmd.replace(self.UNIQUE_PATH_DELIMITER + need_unique_path + self.UNIQUE_PATH_DELIMITER, unique_path)
                for command in cmd.split("&&"):
                    command = command.strip().replace(self.FILE_NAME_PLACEHOLDER, fname)
                    binwalk.core.common.debug("subprocess.call(%s, stdout=%s, stderr=%s)" % (command, str(tmp), str(tmp)))
                    rval = subprocess.call(shlex.split(command), stdout=tmp, stderr=tmp)
                    if rval in codes:
                        retval = True
                    else:
                        retval = False
                    binwalk.core.common.debug('External extractor command "%s" completed with return code %d (success: %s)' % (cmd, rval, str(retval)))
                    command_list.append(command)
        except KeyboardInterrupt as e:
            raise e
        except Exception as e:
            binwalk.core.common.warning("Extractor.execute failed to run external extractor '%s': %s, '%s' might not be installed correctly" % (str(cmd), str(e), str(cmd)))
            retval = None
        if tmp is not None:
            tmp.close()
        return (retval, '&&'.join(command_list))

class ExtractDetails(object):
class ExtractInfo(object):
class Extractor(Module):
    UNIQUE_PATH_DELIMITER = '%%'
    def add_pending(self, f):
        if os.path.islink(f) or not self.matryoshka:
            return
        try:
            file_mode = os.stat(f).st_mode
        except OSError as e:
            return
        if stat.S_ISREG(file_mode):
            try:
                fp = binwalk.core.common.BlockFile(f)
                fp.close()
                self.pending.append(f)
            except IOError as e:
                binwalk.core.common.warning("Ignoring file '%s': %s" % (f, str(e)))
        else:
            binwalk.core.common.warning("Ignoring file '%s': Not a regular file" % f)
    def callback(self, r):
        try:
            r.file.size
        except KeyboardInterrupt as e:
            pass
        except Exception as e:
            return
        if not r.size:
            size = r.file.size - r.offset
        else:
            size = r.size
        if r.valid and r.extract and r.display and (not self.max_count or self.extraction_count < self.max_count):
            if not binwalk.core.common.has_key(self.output, r.file.path):
                self.output[r.file.path] = ExtractInfo()
            binwalk.core.common.debug("Extractor callback for %s @%d [%s]" % (r.file.name,
                                                                              r.offset,
                                                                              r.description))
            (extraction_directory, dd_file, scan_extracted_files, extraction_utility) = self.extract(r.offset,
                                                                                                     r.description,
                                                                                                     r.file.path,
                                                                                                     size,
                                                                                                     r.name)
            if extraction_directory and dd_file:
                self.extraction_count += 1
                dd_file_path = os.path.join(extraction_directory, dd_file)
                self.output[r.file.path].carved[r.offset] = dd_file_path
                self.output[r.file.path].extracted[r.offset] = ExtractDetails(files=[], command=extraction_utility)
                directory_listing = set(os.listdir(extraction_directory))
                if not has_key(self.last_directory_listing, extraction_directory):
                    self.last_directory_listing[extraction_directory] = set()
                for f in directory_listing.difference(self.last_directory_listing[extraction_directory]):
                    file_path = os.path.join(extraction_directory, f)
                    real_file_path = os.path.realpath(file_path)
                    self.result(description=file_path, display=False)
                    if real_file_path != dd_file_path:
                        binwalk.core.common.debug("Adding %s (%s) (%s) to file list" % (file_path, f, real_file_path))
                        self.output[r.file.path].extracted[r.offset].files.append(file_path)
                    if file_path != dd_file_path:
                        self.symlink_sanitizer(file_path, extraction_directory)
                        if os.path.isdir(file_path):
                            for root, dirs, files in os.walk(file_path):
                                self.symlink_sanitizer([os.path.join(root, x) for x in dirs+files], extraction_directory)
                                for f in files:
                                    full_path = os.path.join(root, f)
                                    if len(real_file_path.split(self.directory)[1].split(os.path.sep)) <= self.matryoshka:
                                        if scan_extracted_files and self.directory in real_file_path:
                                                self.add_pending(full_path)
                        elif scan_extracted_files and self.directory in real_file_path:
                            self.add_pending(file_path)
                self.last_directory_listing[extraction_directory] = directory_listing
    def build_output_directory(self, path):
        '''
        Set the output directory for extracted files.
        @path - The path to the file that data will be extracted from.
        Returns None.
        '''
        if not has_key(self.extraction_directories, path):
            basedir = os.path.dirname(path)
            basename = os.path.basename(path)
            if basedir != self.directory:
                try:
                    subdir = basedir.split(self.directory)[1][1:]
                except IndexError as e:
                    subdir = ""
            else:
                subdir = ""
            if self.output_directory_override:
                output_directory = os.path.join(self.directory, subdir, self.output_directory_override)
            else:
                outdir = os.path.join(self.directory, subdir, '_' + basename)
                output_directory = unique_file_name(outdir, extension='extracted')
            if not os.path.exists(output_directory):
                os.mkdir(output_directory)
            self.extraction_directories[path] = output_directory
            self.output[path].directory = os.path.realpath(output_directory) + os.path.sep
        else:
            output_directory = self.extraction_directories[path]
        os.chown(output_directory, self.runas_uid, self.runas_gid)
        return output_directory
    def extract(self, offset, description, file_name, size, name=None):
        '''
        Extract an embedded file from the target file, if it matches an extract rule.
        Called automatically by Binwalk.scan().
        @offset      - Offset inside the target file to begin the extraction.
        @description - Description of the embedded file to extract, as returned by libmagic.
        @file_name   - Path to the target file.
        @size        - Number of bytes to extract.
        @name        - Name to save the file as.
        Returns the name of the extracted file (blank string if nothing was extracted).
        '''
        fname = ''
        rule = None
        recurse = False
        command_line = ''
        original_dir = os.getcwd()
        rules = self.match(description)
        file_path = os.path.realpath(file_name)
        if not rules:
            binwalk.core.common.debug("No extraction rules found for '%s'" % description)
            return (None, None, False, str(None))
        else:
            binwalk.core.common.debug("Found %d matching extraction rules" % len(rules))
        output_directory = self.build_output_directory(file_name)
        if not size:
            size = file_size(file_path) - offset
        if os.path.isfile(file_path):
            binwalk.core.common.debug("Changing directory to: %s" % output_directory)
            os.chdir(output_directory)
            if self.extract_into_subdirs:
                offset_dir = "0x%X" % offset
                os.mkdir(offset_dir)
                os.chdir(offset_dir)
            for i in range(0, len(rules)):
                rule = rules[i]
                binwalk.core.common.debug("Processing extraction rule
                if rule['recurse'] in [True, False]:
                    recurse = rule['recurse']
                else:
                    recurse = True
                binwalk.core.common.debug("Extracting %s[%d:] to %s" % (file_path, offset, name))
                fname = self._dd(file_path, offset, size, rule['extension'], output_file_name=name)
                if rule['cmd']:
                    if self.remove_after_execute:
                        fname_md5 = file_md5(fname)
                    binwalk.core.common.debug("Executing extraction command %s" % (str(rule['cmd'])))
                    if self.run_extractors:
                        (extract_ok, command_line) = self.execute(rule['cmd'], fname, rule['codes'])
                    else:
                        extract_ok = True
                        command_line = ''
                    binwalk.core.common.debug("Ran extraction command: %s" % command_line)
                    binwalk.core.common.debug("Extraction successful: %s" % extract_ok)
                    if self.remove_after_execute and (extract_ok == True or i == (len(rules) - 1)):
                        try:
                            if file_md5(fname) == fname_md5:
                                os.unlink(fname)
                        except KeyboardInterrupt as e:
                            raise e
                        except Exception as e:
                            pass
                    if extract_ok == True:
                        break
                    elif i != (len(rules) - 1):
                        try:
                            os.unlink(fname)
                        except KeyboardInterrupt as e:
                            raise e
                        except Exception as e:
                            pass
                else:
                    break
            binwalk.core.common.debug("Changing directory back to: %s" % original_dir)
            os.chdir(original_dir)
        return (output_directory, fname, recurse, command_line)
    def match(self, description):
        '''
        Check to see if the provided description string matches an extract rule.
        Called internally by self.extract().
        @description - Description string to check.
        Returns the associated rule dictionary if a match is found.
        Returns None if no match is found.
        '''
        rules = []
        ordered_rules = []
        description = description.lower()
        for rule in self.extract_rules:
            if rule['regex'].search(description):
                rules.append(rule)
        for rule in rules:
            if callable(rule['cmd']):
                ordered_rules.append(rule)
        for rule in rules:
            if not callable(rule['cmd']):
                ordered_rules.append(rule)
        binwalk.core.common.debug("Found %d/%d matches for '%s'" % (len(ordered_rules), len(self.extract_rules), description))
        return ordered_rules
    def _dd(self, file_name, offset, size, extension, output_file_name=None):
        '''
        Extracts a file embedded inside the target file.
        @file_name        - Path to the target file.
        @offset           - Offset inside the target file where the embedded file begins.
        @size             - Number of bytes to extract.
        @extension        - The file exension to assign to the extracted file on disk.
        @output_file_name - The requested name of the output file.
        Returns the extracted file name.
        '''
        total_size = 0
        default_bname = "%X" % (offset + self.config.base)
        if output_file_name is not None:
            output_file_name = str(output_file_name)
        if self.max_size and size > self.max_size:
            size = self.max_size
        if not output_file_name or output_file_name is None:
            bname = default_bname
        else:
            bname = os.path.basename(output_file_name)
        fname = unique_file_name(bname, extension)
        try:
            if self.config.swap_size:
                adjust = offset % self.config.swap_size
            else:
                adjust = 0
            offset -= adjust
            fdin = self.config.open_file(file_name)
            fdin.seek(offset)
            try:
                fdout = BlockFile(fname, 'w')
            except KeyboardInterrupt as e:
                raise e
            except Exception as e:
                fname = unique_file_name(default_bname, extension)
                fdout = BlockFile(fname, 'w')
            while total_size < size:
                (data, dlen) = fdin.read_block()
                if dlen < 1:
                    break
                else:
                    total_size += (dlen - adjust)
                    if total_size > size:
                        dlen -= (total_size - size)
                    fdout.write(str2bytes(data[adjust:dlen]))
                    adjust = 0
            fdout.close()
            fdin.close()
            os.chown(fname, self.runas_uid, self.runas_gid)
        except KeyboardInterrupt as e:
            raise e
        except Exception as e:
            raise Exception("Extractor.dd failed to extract data from '%s' to '%s': %s" %
                            (file_name, fname, str(e)))
        binwalk.core.common.debug("Carved data block 0x%X - 0x%X from '%s' to '%s'" %
                                  (offset, offset + size, file_name, fname))
        return fname
    def execute(self, cmd, fname, codes=[0, None]):
        '''
        Execute a command against the specified file.
        @cmd   - Command to execute.
        @fname - File to run command against.
        @codes - List of return codes indicating cmd success.
        Returns True on success, False on failure, or None if the external extraction utility could not be found.
        '''
        rval = 0
        retval = True
        command_list = []
        binwalk.core.common.debug("Running extractor '%s'" % str(cmd))
        try:
            if callable(cmd):
                command_list.append(get_class_name_from_method(cmd))
                try:
                    retval = cmd(fname)
                except KeyboardInterrupt as e:
                    raise e
                except Exception as e:
                    retval = False
                    binwalk.core.common.warning("Internal extractor '%s' failed with exception: '%s'" % (str(cmd), str(e)))
            elif cmd:
                while self.UNIQUE_PATH_DELIMITER in cmd:
                    need_unique_path = cmd.split(self.UNIQUE_PATH_DELIMITER)[1].split(self.UNIQUE_PATH_DELIMITER)[0]
                    unique_path = binwalk.core.common.unique_file_name(need_unique_path)
                    cmd = cmd.replace(self.UNIQUE_PATH_DELIMITER + need_unique_path + self.UNIQUE_PATH_DELIMITER, unique_path)
                for command in cmd.split("&&"):
                    command = command.strip().replace(self.FILE_NAME_PLACEHOLDER, fname)
                    rval = self.shell_call(command)
                    if rval in codes:
                        retval = True
                    else:
                        retval = False
                    binwalk.core.common.debug('External extractor command "%s" completed with return code %d (success: %s)' % (cmd, rval, str(retval)))
                    command_list.append(command)
        except KeyboardInterrupt as e:
            raise e
        except Exception as e:
            binwalk.core.common.warning("Extractor.execute failed to run external extractor '%s': %s, '%s' might not be installed correctly" % (str(cmd), str(e), str(cmd)))
            retval = None
        return (retval, '&&'.join(command_list))
    def shell_call(self, command):
        if not binwalk.core.common.DEBUG:
            tmp = subprocess.DEVNULL
        else:
            tmp = None
        if self.runas_uid != os.getuid():
            binwalk.core.common.debug("Switching privileges to %s (%d:%d)" % (self.runas_user, self.runas_uid, self.runas_gid))
            child_pid = os.fork()
            if child_pid is 0:
                if self.runas_uid is not None and self.runas_gid is not None:
                    os.setgid(self.runas_uid)
                    os.setuid(self.runas_gid)
        else:
            child_pid = None
        if child_pid in [0, None]:
            binwalk.core.common.debug("subprocess.call(%s, stdout=%s, stderr=%s)" % (command, str(tmp), str(tmp)))
            rval = subprocess.call(shlex.split(command), stdout=tmp, stderr=tmp)
        if child_pid is 0:
            sys.exit(rval)
        elif child_pid is None:
            return rval
        else:
            return os.wait()[1]
    def symlink_sanitizer(self, file_list, extraction_directory):
        if self.do_not_sanitize_symlinks is True:
            return
        if type(file_list) is not list:
            file_list = [file_list]
        for file_name in file_list:
            if os.path.islink(file_name):
                linktarget = os.path.realpath(file_name)
                binwalk.core.common.debug("Analysing symlink: %s -> %s" % (file_name, linktarget))
                if not linktarget.startswith(extraction_directory) and linktarget != os.devnull:
                    binwalk.core.common.warning("Symlink points outside of the extraction directory: %s -> %s; changing link target to %s for security purposes." % (file_name, linktarget, os.devnull))
                    os.remove(file_name)
                    os.symlink(os.devnull, file_name)

