            self.can_read,
            self.can_write,
            self.can_move,
            self.can_delete,
            self.can_get,
            self.can_upget,
            self.can_admin,
        ) = (
            avn.can_access("", self.uname) if avn else [False] * 7
        )
        self.avn = avn
        self.vn = vn
        self.rem = rem
