            + "  (if you crash with codec errors then that is why)"
        )
    if PY2 and al.smb:
        print("error: python2 cannot --smb")
        return
    if sys.version_info < (3, 6):
        al.no_scandir = True
    SvcHub(al, dal, argv, "".join(printed)).run()

