def month_boundaries(months: int, tzstr: str) -> list[datetime]:
    tz = ZoneInfo(tzstr)
    result: list[datetime] = []
    now = timezone.now().astimezone(tz)
    y, m = now.year, now.month
    for x in range(0, months):
        result.insert(0, datetime(y, m, 1, tzinfo=tz))
        m -= 1
        if m == 0:
            m = 12
            y = y - 1
    return result

