                try:
                    for match in re.finditer(pattern, fin):
                        description, url = match.groups()
                        if url.startswith("/"):
                            url = url[1:]
                        url = unquote(url)
                        if os.path.exists(cfg.wiki_directory+"/"+url+".md"):
                            info = {
                                "filename": url,
                            }
                            value["links"].append(info)
                            print(url)
                except Exception as e:
                    print("error: ", e)
            links.append(value)
    links = extend_ids(links)
    return links
def move_all_files(src_dir: str, dest_dir: str):
    """
    Function that moves all the files from a source directory to a destination one.
    If a file with the same name is already present in the destination, the source file will be renamed with a
    '-copy-XX' suffix.
    :param src_dir: source directory
    :param dest_dir: destination directory
    """
    if not os.path.isdir(dest_dir):
        os.mkdir(dest_dir)
    src_files = os.listdir(src_dir)
    dest_files = os.listdir(dest_dir)
    for file in src_files:
        new_file = file
        copies_count = 1
        while new_file in dest_files:
            file_split = file.split('.')
            new_file = f"{file_split[0]}-copy-{copies_count}"
            if len(file_split) > 1:
                new_file += f".{file_split[1]}"
            copies_count += 1
        os.rename(f"{src_dir}/{file}", f"{dest_dir}/{new_file}")

