                             allow_keyring=True):
        """Find and return credentials for the specified URL."""
        url, netloc, url_user_password = split_auth_netloc_from_url(
            original_url)
        username, password = url_user_password
        if username is not None and password is not None:
            logger.debug("Found credentials in url for %s", netloc)
            return url_user_password
        index_url = self._get_index_url(url)
        if index_url:
            index_info = split_auth_netloc_from_url(index_url)
            if index_info:
                index_url, _, index_url_user_password = index_info
                logger.debug("Found index url %s", index_url)
        if index_url and index_url_user_password[0] is not None:
            username, password = index_url_user_password
            if username is not None and password is not None:
                logger.debug("Found credentials in index url for %s", netloc)
                return index_url_user_password
        if allow_netrc:
            netrc_auth = get_netrc_auth(original_url)
            if netrc_auth:
                logger.debug("Found credentials in netrc for %s", netloc)
                return netrc_auth
        if allow_keyring:
            kr_auth = (_get_keyring_auth(index_url, username) or
                       _get_keyring_auth(netloc, username))
            if kr_auth:
                logger.debug("Found credentials in keyring for %s", netloc)
                return kr_auth
        return None, None
    def _get_url_and_credentials(self, original_url):
        """Return the credentials to use for the provided URL.
        If allowed, netrc and keyring may be used to obtain the
        correct credentials.
        Returns (url_without_credentials, username, password). Note
        that even if the original URL contains credentials, this
        function may return a different username and password.
        """
        url, netloc, _ = split_auth_netloc_from_url(original_url)
        username, password = self.passwords.get(netloc, (None, None))
        if username is None or password is None:
            username, password = self._get_new_credentials(original_url)
        if username is not None and password is not None:
            self.passwords[netloc] = (username, password)
        return url, username, password
    def __call__(self, req):
        url, username, password = self._get_url_and_credentials(req.url)
        req.url = url
        if username is not None and password is not None:
            req = HTTPBasicAuth(username, password)(req)
        req.register_hook("response", self.handle_401)
        return req
    def _prompt_for_password(self, netloc):
        username = ask_input("User for %s: " % netloc)
        if not username:
            return None, None
        auth = _get_keyring_auth(netloc, username)
        if auth:
            return auth[0], auth[1], False
        password = ask_password("Password: ")
        return username, password, True
    def handle_401(self, resp, **kwargs):
        if resp.status_code != 401:
            return resp
        if not self.prompting:
            return resp
        parsed = urllib_parse.urlparse(resp.url)
        username, password, save = self._prompt_for_password(parsed.netloc)
        self._credentials_to_save = None
        if username is not None and password is not None:
            self.passwords[parsed.netloc] = (username, password)
            if save and self._should_save_password_to_keyring():
                self._credentials_to_save = (parsed.netloc, username, password)
        resp.content
        resp.raw.release_conn()
        req = HTTPBasicAuth(username or "", password or "")(resp.request)
        req.register_hook("response", self.warn_on_401)
        if self._credentials_to_save:
            req.register_hook("response", self.save_credentials)
        new_resp = resp.connection.send(req, **kwargs)
        new_resp.history.append(resp)
        return new_resp
    def warn_on_401(self, resp, **kwargs):
        """Response callback to warn about incorrect credentials."""
        if resp.status_code == 401:
            logger.warning('401 Error, Credentials not correct for %s',
                           resp.request.url)
    def save_credentials(self, resp, **kwargs):
        """Response callback to save credentials on success."""
        assert keyring is not None, "should never reach here without keyring"
        if not keyring:
            return
        creds = self._credentials_to_save
        self._credentials_to_save = None
        if creds and resp.status_code < 400:
            try:
                logger.info('Saving credentials to keyring')
                keyring.set_password(*creds)
            except Exception:
                logger.exception('Failed to save credentials')
class LocalFSAdapter(BaseAdapter):
    def send(self, request, stream=None, timeout=None, verify=None, cert=None,
             proxies=None):
        pathname = url_to_path(request.url)
        resp = Response()
        resp.status_code = 200
        resp.url = request.url
        try:
            stats = os.stat(pathname)
        except OSError as exc:
            resp.status_code = 404
            resp.raw = exc
        else:
            modified = email.utils.formatdate(stats.st_mtime, usegmt=True)
            content_type = mimetypes.guess_type(pathname)[0] or "text/plain"
            resp.headers = CaseInsensitiveDict({
                "Content-Type": content_type,
                "Content-Length": stats.st_size,
                "Last-Modified": modified,
            })
            resp.raw = open(pathname, "rb")
            resp.close = resp.raw.close
        return resp
class SafeFileCache(FileCache):
    def __init__(self, *args, **kwargs):
        super(SafeFileCache, self).__init__(*args, **kwargs)
        if not check_path_owner(self.directory):
            logger.warning(
                "The directory '%s' or its parent directory is not owned by "
                "the current user and the cache has been disabled. Please "
                "check the permissions and owner of that directory. If "
                "executing pip with sudo, you may want sudo's -H flag.",
                self.directory,
            )
            self.directory = None
    def get(self, *args, **kwargs):
        if self.directory is None:
            return
        try:
            return super(SafeFileCache, self).get(*args, **kwargs)
        except (LockError, OSError, IOError):
            pass
class PipSession(requests.Session):
    def __init__(self, *args, **kwargs):
        retries = kwargs.pop("retries", 0)
        cache = kwargs.pop("cache", None)
        insecure_hosts = kwargs.pop("insecure_hosts", [])
        index_urls = kwargs.pop("index_urls", None)
        super(PipSession, self).__init__(*args, **kwargs)
        self.headers["User-Agent"] = user_agent()
        self.auth = MultiDomainBasicAuth(index_urls=index_urls)
        retries = urllib3.Retry(
            total=retries,
            status_forcelist=[500, 503, 520, 527],
            backoff_factor=0.25,
        )
        if cache:
            secure_adapter = CacheControlAdapter(
                cache=SafeFileCache(cache, use_dir_lock=True),
                max_retries=retries,
            )
        else:
            secure_adapter = HTTPAdapter(max_retries=retries)
        insecure_adapter = InsecureHTTPAdapter(max_retries=retries)
        self.mount("https://", secure_adapter)
        self.mount("http://", insecure_adapter)
        self.mount("file://", LocalFSAdapter())
        for host in insecure_hosts:
            self.mount("https://{}/".format(host), insecure_adapter)
def get_file_content(url, comes_from=None, session=None):
    """Gets the content of a file; it may be a filename, file: URL, or
    http: URL.  Returns (location, content).  Content is unicode.
    :param url:         File path or url.
    :param comes_from:  Origin description of requirements.
    :param session:     Instance of pip.download.PipSession.
    """
    if session is None:
        raise TypeError(
            "get_file_content() missing 1 required keyword argument: 'session'"
        )
    match = _scheme_re.search(url)
    if match:
        scheme = match.group(1).lower()
        if (scheme == 'file' and comes_from and
                comes_from.startswith('http')):
            raise InstallationError(
                'Requirements file %s references URL %s, which is local'
                % (comes_from, url))
        if scheme == 'file':
            path = url.split(':', 1)[1]
            path = path.replace('\\', '/')
            match = _url_slash_drive_re.match(path)
            if match:
                path = match.group(1) + ':' + path.split('|', 1)[1]
            path = urllib_parse.unquote(path)
            if path.startswith('/'):
                path = '/' + path.lstrip('/')
            url = path
        else:
            resp = session.get(url)
            resp.raise_for_status()
            return resp.url, resp.text
    try:
        with open(url, 'rb') as f:
            content = auto_decode(f.read())
    except IOError as exc:
        raise InstallationError(
            'Could not open requirements file: %s' % str(exc)
        )
    return url, content
def url_to_path(url):
    """
    Convert a file: URL to a path.
    """
    assert url.startswith('file:'), (
        "You can only turn file: urls into filenames (not %r)" % url)
    _, netloc, path, _, _ = urllib_parse.urlsplit(url)
    if not netloc or netloc == 'localhost':
        netloc = ''
    elif sys.platform == 'win32':
        netloc = '\\\\' + netloc
    else:
        raise ValueError(
            'non-local file URIs are not supported on this platform: %r'
            % url
        )
    path = urllib_request.url2pathname(netloc + path)
    return path
def is_file_url(link):
    return link.url.lower().startswith('file:')
def is_dir_url(link):
    """Return whether a file:// Link points to a directory.
    ``link`` must not have any other scheme but file://. Call is_file_url()
    first.
    """
    link_path = url_to_path(link.url_without_fragment)
    return os.path.isdir(link_path)
def _progress_indicator(iterable, *args, **kwargs):
    return iterable
def _download_url(
    resp,
    link,
    content_file,
    hashes,
    progress_bar
):
    try:
        total_length = int(resp.headers['content-length'])
    except (ValueError, KeyError, TypeError):
        total_length = 0
    cached_resp = getattr(resp, "from_cache", False)
    if logger.getEffectiveLevel() > logging.INFO:
        show_progress = False
    elif cached_resp:
        show_progress = False
    elif total_length > (40 * 1000):
        show_progress = True
    elif not total_length:
        show_progress = True
    else:
        show_progress = False
    show_url = link.show_url
    def resp_read(chunk_size):
        try:
            for chunk in resp.raw.stream(
                    chunk_size,
                    decode_content=False):
                yield chunk
        except AttributeError:
            while True:
                chunk = resp.raw.read(chunk_size)
                if not chunk:
                    break
                yield chunk
    def written_chunks(chunks):
        for chunk in chunks:
            content_file.write(chunk)
            yield chunk
    progress_indicator = _progress_indicator
    if link.netloc == PyPI.netloc:
        url = show_url
    else:
        url = link.url_without_fragment
    if show_progress:
        progress_indicator = DownloadProgressProvider(progress_bar,
                                                      max=total_length)
        if total_length:
            logger.info("Downloading %s (%s)", url, format_size(total_length))
        else:
            logger.info("Downloading %s", url)
    elif cached_resp:
        logger.info("Using cached %s", url)
    else:
        logger.info("Downloading %s", url)
    logger.debug('Downloading from URL %s', link)
    downloaded_chunks = written_chunks(
        progress_indicator(
            resp_read(CONTENT_CHUNK_SIZE),
            CONTENT_CHUNK_SIZE
        )
    )
    if hashes:
        hashes.check_against_chunks(downloaded_chunks)
    else:
        consume(downloaded_chunks)
def _copy_file(filename, location, link):
    copy = True
    download_location = os.path.join(location, link.filename)
    if os.path.exists(download_location):
        response = ask_path_exists(
            'The file %s exists. (i)gnore, (w)ipe, (b)ackup, (a)abort' %
            display_path(download_location), ('i', 'w', 'b', 'a'))
        if response == 'i':
            copy = False
        elif response == 'w':
            logger.warning('Deleting %s', display_path(download_location))
            os.remove(download_location)
        elif response == 'b':
            dest_file = backup_dir(download_location)
            logger.warning(
                'Backing up %s to %s',
                display_path(download_location),
                display_path(dest_file),
            )
            shutil.move(download_location, dest_file)
        elif response == 'a':
            sys.exit(-1)
    if copy:
        shutil.copy(filename, download_location)
        logger.info('Saved %s', display_path(download_location))
def unpack_http_url(
    link,
    location,
    download_dir=None,
    session=None,
    hashes=None,
    progress_bar="on"
):
    if session is None:
        raise TypeError(
            "unpack_http_url() missing 1 required keyword argument: 'session'"
        )
    with TempDirectory(kind="unpack") as temp_dir:
        already_downloaded_path = None
        if download_dir:
            already_downloaded_path = _check_download_dir(link,
                                                          download_dir,
                                                          hashes)
        if already_downloaded_path:
            from_path = already_downloaded_path
            content_type = mimetypes.guess_type(from_path)[0]
        else:
            from_path, content_type = _download_http_url(link,
                                                         session,
                                                         temp_dir.path,
                                                         hashes,
                                                         progress_bar)
        unpack_file(from_path, location, content_type, link)
        if download_dir and not already_downloaded_path:
            _copy_file(from_path, download_dir, link)
        if not already_downloaded_path:
            os.unlink(from_path)
def unpack_file_url(
    link,
    location,
    download_dir=None,
    hashes=None
):
    """Unpack link into location.
    If download_dir is provided and link points to a file, make a copy
    of the link file inside download_dir.
    """
    link_path = url_to_path(link.url_without_fragment)
    if is_dir_url(link):
        if os.path.isdir(location):
            rmtree(location)
        shutil.copytree(link_path, location, symlinks=True)
        if download_dir:
            logger.info('Link is a directory, ignoring download_dir')
        return
    if hashes:
        hashes.check_against_path(link_path)
    already_downloaded_path = None
    if download_dir:
        already_downloaded_path = _check_download_dir(link,
                                                      download_dir,
                                                      hashes)
    if already_downloaded_path:
        from_path = already_downloaded_path
    else:
        from_path = link_path
    content_type = mimetypes.guess_type(from_path)[0]
    unpack_file(from_path, location, content_type, link)
    if download_dir and not already_downloaded_path:
        _copy_file(from_path, download_dir, link)
    def request(self, host, handler, request_body, verbose=False):
        parts = (self._scheme, host, handler, None, None, None)
        url = urllib_parse.urlunparse(parts)
        try:
            headers = {'Content-Type': 'text/xml'}
            response = self._session.post(url, data=request_body,
                                          headers=headers, stream=True)
            response.raise_for_status()
            self.verbose = verbose
            return self.parse_response(response.raw)
        except requests.HTTPError as exc:
            logger.critical(
                "HTTP error %s while getting %s",
                exc.response.status_code, url,
            )
            raise
def unpack_url(
    link,
    location,
    download_dir=None,
    only_download=False,
    session=None,
    hashes=None,
    progress_bar="on"
):
    """Unpack link.
       If link is a VCS link:
         if only_download, export into download_dir and ignore location
          else unpack into location
       for other types of link:
         - unpack into location
         - if download_dir, copy the file into download_dir
         - if only_download, mark location for deletion
    :param hashes: A Hashes object, one of whose embedded hashes must match,
        or HashMismatch will be raised. If the Hashes is empty, no matches are
        required, and unhashable types of requirements (like VCS ones, which
        would ordinarily raise HashUnsupported) are allowed.
    """
    if is_vcs_url(link):
        unpack_vcs_link(link, location)
    elif is_file_url(link):
        unpack_file_url(link, location, download_dir, hashes=hashes)
    else:
        if session is None:
            session = PipSession()
        unpack_http_url(
            link,
            location,
            download_dir,
            session,
            hashes=hashes,
            progress_bar=progress_bar
        )
    if only_download:
        write_delete_marker_file(location)
def _download_http_url(
    link,
    session,
    temp_dir,
    hashes,
    progress_bar
):
    """Download link url into temp_dir using provided session"""
    target_url = link.url.split('
    try:
        resp = session.get(
            target_url,
            headers={"Accept-Encoding": "identity"},
            stream=True,
        )
        resp.raise_for_status()
    except requests.HTTPError as exc:
        logger.critical(
            "HTTP error %s while getting %s", exc.response.status_code, link,
        )
        raise
    content_type = resp.headers.get('content-type', '')
    filename = link.filename
    content_disposition = resp.headers.get('content-disposition')
    if content_disposition:
        type, params = cgi.parse_header(content_disposition)
        filename = params.get('filename') or filename
    ext = splitext(filename)[1]
    if not ext:
        ext = mimetypes.guess_extension(content_type)
        if ext:
            filename += ext
    if not ext and link.url != resp.url:
        ext = os.path.splitext(resp.url)[1]
        if ext:
            filename += ext
    file_path = os.path.join(temp_dir, filename)
    with open(file_path, 'wb') as content_file:
        _download_url(resp, link, content_file, hashes, progress_bar)
    return file_path, content_type
def _check_download_dir(link, download_dir, hashes):
    """ Check download_dir for previously downloaded file with correct hash
        If a correct file is found return its path else None
    """
    download_path = os.path.join(download_dir, link.filename)
    if os.path.exists(download_path):
        logger.info('File was already downloaded %s', download_path)
        if hashes:
            try:
                hashes.check_against_path(download_path)
            except HashMismatch:
                logger.warning(
                    'Previously-downloaded file %s has bad hash. '
                    'Re-downloading.',
                    download_path
                )
                os.unlink(download_path)
                return None
        return download_path
    return None

logger = logging.getLogger(__name__)
def looks_like_ci():
    """
    Return whether it looks like pip is running under CI.
    """
    return any(name in os.environ for name in CI_ENVIRONMENT_VARIABLES)
def user_agent():
    """
    Return a string representing the user agent.
    """
    data = {
        "installer": {"name": "pip", "version": pip.__version__},
        "python": platform.python_version(),
        "implementation": {
            "name": platform.python_implementation(),
        },
    }
    if data["implementation"]["name"] == 'CPython':
        data["implementation"]["version"] = platform.python_version()
    elif data["implementation"]["name"] == 'PyPy':
        if sys.pypy_version_info.releaselevel == 'final':
            pypy_version_info = sys.pypy_version_info[:3]
        else:
            pypy_version_info = sys.pypy_version_info
        data["implementation"]["version"] = ".".join(
            [str(x) for x in pypy_version_info]
        )
    elif data["implementation"]["name"] == 'Jython':
        data["implementation"]["version"] = platform.python_version()
    elif data["implementation"]["name"] == 'IronPython':
        data["implementation"]["version"] = platform.python_version()
    if sys.platform.startswith("linux"):
        from pip._vendor import distro
        distro_infos = dict(filter(
            lambda x: x[1],
            zip(["name", "version", "id"], distro.linux_distribution()),
        ))
        libc = dict(filter(
            lambda x: x[1],
            zip(["lib", "version"], libc_ver()),
        ))
        if libc:
            distro_infos["libc"] = libc
        if distro_infos:
            data["distro"] = distro_infos
    if sys.platform.startswith("darwin") and platform.mac_ver()[0]:
        data["distro"] = {"name": "macOS", "version": platform.mac_ver()[0]}
    if platform.system():
        data.setdefault("system", {})["name"] = platform.system()
    if platform.release():
        data.setdefault("system", {})["release"] = platform.release()
    if platform.machine():
        data["cpu"] = platform.machine()
    if HAS_TLS:
        data["openssl_version"] = ssl.OPENSSL_VERSION
    setuptools_version = get_installed_version("setuptools")
    if setuptools_version is not None:
        data["setuptools_version"] = setuptools_version
    data["ci"] = True if looks_like_ci() else None
    user_data = os.environ.get("PIP_USER_AGENT_USER_DATA")
    if user_data is not None:
        data["user_data"] = user_data
    return "{data[installer][name]}/{data[installer][version]} {json}".format(
        data=data,
        json=json.dumps(data, separators=(",", ":"), sort_keys=True),
    )
def _get_keyring_auth(url, username):
    """Return the tuple auth for a given url from keyring."""
    if not url or not keyring:
        return None
    try:
        try:
            get_credential = keyring.get_credential
        except AttributeError:
            pass
        else:
            logger.debug("Getting credentials from keyring for %s", url)
            cred = get_credential(url, username)
            if cred is not None:
                return cred.username, cred.password
            return None
        if username:
            logger.debug("Getting password from keyring for %s", url)
            password = keyring.get_password(url, username)
            if password:
                return username, password
    except Exception as exc:
        logger.warning("Keyring is skipped due to an exception: %s",
                       str(exc))
class MultiDomainBasicAuth(AuthBase):
    def _get_index_url(self, url):
        """Return the original index URL matching the requested URL.
        Cached or dynamically generated credentials may work against
        the original index URL rather than just the netloc.
        The provided url should have had its username and password
        removed already. If the original index url had credentials then
        they will be included in the return value.
        Returns None if no matching index was found, or if --no-index
        was specified by the user.
        """
        if not url or not self.index_urls:
            return None
        for u in self.index_urls:
            prefix = remove_auth_from_url(u).rstrip("/") + "/"
            if url.startswith(prefix):
                return u
    def _get_new_credentials(self, original_url, allow_netrc=True,
                             allow_keyring=True):
        """Find and return credentials for the specified URL."""
        url, netloc, url_user_password = split_auth_netloc_from_url(
            original_url)
        username, password = url_user_password
        if username is not None and password is not None:
            logger.debug("Found credentials in url for %s", netloc)
            return url_user_password
        index_url = self._get_index_url(url)
        if index_url:
            index_info = split_auth_netloc_from_url(index_url)
            if index_info:
                index_url, _, index_url_user_password = index_info
                logger.debug("Found index url %s", index_url)
        if index_url and index_url_user_password[0] is not None:
            username, password = index_url_user_password
            if username is not None and password is not None:
                logger.debug("Found credentials in index url for %s", netloc)
                return index_url_user_password
        if allow_netrc:
            netrc_auth = get_netrc_auth(original_url)
            if netrc_auth:
                logger.debug("Found credentials in netrc for %s", netloc)
                return netrc_auth
        if allow_keyring:
            kr_auth = (_get_keyring_auth(index_url, username) or
                       _get_keyring_auth(netloc, username))
            if kr_auth:
                logger.debug("Found credentials in keyring for %s", netloc)
                return kr_auth
        return None, None
    def _get_url_and_credentials(self, original_url):
        """Return the credentials to use for the provided URL.
        If allowed, netrc and keyring may be used to obtain the
        correct credentials.
        Returns (url_without_credentials, username, password). Note
        that even if the original URL contains credentials, this
        function may return a different username and password.
        """
        url, netloc, _ = split_auth_netloc_from_url(original_url)
        username, password = self.passwords.get(netloc, (None, None))
        if username is None or password is None:
            username, password = self._get_new_credentials(original_url)
        if username is not None and password is not None:
            self.passwords[netloc] = (username, password)
        return url, username, password
    def __call__(self, req):
        url, username, password = self._get_url_and_credentials(req.url)
        req.url = url
        if username is not None and password is not None:
            req = HTTPBasicAuth(username, password)(req)
        req.register_hook("response", self.handle_401)
        return req
    def _prompt_for_password(self, netloc):
        username = ask_input("User for %s: " % netloc)
        if not username:
            return None, None
        auth = _get_keyring_auth(netloc, username)
        if auth:
            return auth[0], auth[1], False
        password = ask_password("Password: ")
        return username, password, True
    def handle_401(self, resp, **kwargs):
        if resp.status_code != 401:
            return resp
        if not self.prompting:
            return resp
        parsed = urllib_parse.urlparse(resp.url)
        username, password, save = self._prompt_for_password(parsed.netloc)
        self._credentials_to_save = None
        if username is not None and password is not None:
            self.passwords[parsed.netloc] = (username, password)
            if save and self._should_save_password_to_keyring():
                self._credentials_to_save = (parsed.netloc, username, password)
        resp.content
        resp.raw.release_conn()
        req = HTTPBasicAuth(username or "", password or "")(resp.request)
        req.register_hook("response", self.warn_on_401)
        if self._credentials_to_save:
            req.register_hook("response", self.save_credentials)
        new_resp = resp.connection.send(req, **kwargs)
        new_resp.history.append(resp)
        return new_resp
    def warn_on_401(self, resp, **kwargs):
        """Response callback to warn about incorrect credentials."""
        if resp.status_code == 401:
            logger.warning('401 Error, Credentials not correct for %s',
                           resp.request.url)
